+		: changed
+			? "학습 연도마다 방향 부호가 달라, 해마다 부호가 바뀐다."
+			: sign >= 0
+				? "학습 구간에서 방향 부호가 +1이라 순방향으로 들어간다."
+				: "학습 구간에서 방향 부호가 -1이라 역추세로 들어간다.";
+	const tiles: ScreenTile[] = [
