// Fixture adapter for the research API until quantd serves GET /api/v1/research/*.
// fixture.json is a copy of .product/data/research.json. Verdicts and metrics are shown as
// delivered, never recomputed in the UI.
import FlaskConicalIcon from "@lucide/svelte/icons/flask-conical";
import ScaleIcon from "@lucide/svelte/icons/scale";
import fixture from "./fixture.json";

// "pending" = the engine has not computed the after-tax CAGR yet (E5). Nothing is judged and no number is shown.
export type Verdict = "passed" | "rejected" | "undecided" | "running" | "pending";
export type GateStatus = "passed" | "failed" | "undecided" | "waiting";
export type ExperimentState =
	"초안" | "봉인됨" | "실행중" | "실행실패" | "취소됨" | "평가완료" | "연구기각" | "연구통과";

export interface AnnualRow {
	year: number;
	candidate: number;
	benchmark: number;
	sameExposure?: number;
}

/** The strategy a candidate runs: a spec id and one of its variants (e.g. `long+kelly`). */
export interface StrategyRef {
	id: string;
	variant: string;
}

/**
 * quant-sweep Summary row of the candidate's spec variant over the whole snapshot (engine output, bps, verbatim).
 * In-sample: it shows how the variants differ, it is not a judgment basis (E5 judges).
 * `wins`·`winRateBps`·`avgRBps`… are 0 when nothing closed; `finalEquityE8`·`maxDdEquityBps` are 0 in R mode.
 */
export interface EngineStats {
	trades: number;
	wins: number;
	losses: number;
	open: number;
	winRateBps: number;
	avgRBps: number;
	sumRBps: number;
	maxDdRBps: number;
	taken: number;
	skipped: number;
	finalEquityE8: number;
	maxDdEquityBps: number;
	tradeHash: string;
}

/** How an experiment's engine stats were run (one sweep for every variant). */
export interface EngineRun {
	tool: string;
	engineRev: string;
	specHash: string;
	snapshotHash: string;
	from: string;
	to: string;
	bars: number;
	costBpsPerSide: number;
	params: Record<string, number>;
	variantParams: Record<string, Record<string, number>>;
	inSample: boolean;
}

interface CandidateBase {
	id: string;
	experimentId: string;
	code: string;
	name: string;
	switches: string;
	leverage: number;
	verdictSentence: string;
	/** Present when the candidate is a strategy spec variant; the structure tab reads it. */
	strategy?: StrategyRef;
	engineStats?: EngineStats;
}

export interface ScoredCandidate extends CandidateBase {
	afterTaxCagr: number;
	benchmarkCagr: number;
	excessCagr: number;
	excessCi: [number, number];
	mdd: number;
	benchmarkMdd: number;
	verdict: Exclude<Verdict, "pending">;
	annual: AnnualRow[];
	sameExposure?: { label: string; afterTaxCagr: number; mdd: number; excessCagr: number };
	equity?: { months: string[]; candidate: number[]; benchmark: number[]; sameExposure?: number[] };
	drawdown?: { candidate: number[]; benchmark: number[] };
	exposure?: number[];
}

/** Not computed yet: every metric is null, never a placeholder number. */
export interface PendingCandidate extends CandidateBase {
	afterTaxCagr: null;
	benchmarkCagr: null;
	excessCagr: null;
	excessCi: null;
	mdd: null;
	benchmarkMdd: null;
	verdict: "pending";
	annual: null;
}

export type Candidate = ScoredCandidate | PendingCandidate;

export function isScored(c: Candidate): c is ScoredCandidate {
	return c.verdict !== "pending";
}

/** A strategy variant the engine has not judged yet: its only content is the experiment's structure section. */
export function opensStructure(c: Candidate | undefined): boolean {
	return !!c && !isScored(c) && !!c.strategy;
}

export interface Experiment {
	id: string;
	name: string;
	hypothesis: string;
	state: ExperimentState;
	candidates: number;
	topExcessCagr: number | null;
	updatedAt: string;
	specHash: string | null;
	sealedAt: string | null;
	runs: { done: number; total: number };
	engineRun?: EngineRun;
}

export interface Gate {
	id: string;
	name: string;
	definition: string;
	status: GateStatus;
	reason: string;
}

export interface Fold {
	id: string;
	testYear: number;
	warmup: [string, string];
	train: [string, string];
	gap1: [string, string];
	validation: [string, string];
	gap2: [string, string];
	test: [string, string];
	diff: number;
	trainExcess: number;
	testPath: number[];
}

export interface Evidence {
	folds: Fold[];
	lockbox: [string, string];
	bootstrap: {
		lo: number;
		hi: number;
		blockSessions: number;
		resamples: number;
		seed: number;
		histogram: { from: number; step: number; counts: number[] };
	};
	trials: { total: number; inExperiment: number; deflatedSharpe: string };
	gap: string;
}

export interface PipelineStage {
	id: string;
	label: string;
	count: number;
	pending?: number;
	rejected?: number;
	undecided?: number;
	note: string;
}

export interface GateFlowStep {
	gate: string;
	passed: string[];
	rejected: { id: string; reason: string }[];
	undecided: string[];
}

export interface RunMatrix {
	phase: string;
	stresses: { id: string; label: string }[];
	folds: { id: string; year: number }[];
	/** `label` replaces the stress column text for that row (a screen shows its horizon there). */
	rows: {
		candidate: string;
		label?: string;
		cells: { stress: string; year: number; diff: number; gate0: "passed" | "failed" }[];
	}[];
	note: string;
}

export interface StressRow {
	id: string;
	label: string;
	group: string;
	excess: number | null;
	ci: [number, number] | null;
	mdd: number | null;
	verdict: Verdict | "waiting";
	status: "run" | "unsupported";
	reason?: string;
}

export interface StressReport {
	waterfall: { id: string; label: string; value: number; kind: "total" | "step" }[];
	benchmarkNet: number;
	costDrag: number;
	turnover: { annual: number; trades: number };
	rows: StressRow[];
}

export interface SnapshotSeries {
	id: string;
	label: string;
	source: string;
	from: string;
	to: string;
	sessions: number;
	missing: number;
	sha: string;
	gaps: [string, string][];
}

export interface Snapshot {
	id: string;
	hash: string;
	createdAt: string;
	schema: string;
	lockbox: [string, string];
	series: SnapshotSeries[];
	issues: { level: "warning" | "info"; series: string; text: string }[];
	survivorship: string;
	usedBy: string[];
}

export interface Bundle {
	id: string;
	portfolio: string;
	version: string;
	verdict: string;
	state: string;
	signedBy: string;
	createdAt: string;
	signature: "ok" | "mismatch";
	note: string;
}


