 export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

+/** The trial at horizon `h`, falling back to the lead trial when the feature lacks that horizon. */
+export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
+	if (h === "lead") return leadTrial(f);
+	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
+}
+
+/** Round chart ticks covering [min, max], always including 0 when the range spans it. */
+export function niceTicks(min: number, max: number): number[] {
+	if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
+	const lo = Math.min(min, max);
+	const hi = Math.max(min, max);
+	const range = hi - lo;
+	if (range <= 0) return [lo];
+	const raw = range / 5;
+	const mag = 10 ** Math.floor(Math.log10(raw));
+	const base = raw / mag;
+	const niceBase = [1, 2, 2.5, 5, 10].reduce((best, c) => (Math.abs(Math.log10(c / base)) < Math.abs(Math.log10(best / base)) ? c : best));
+	const step = niceBase * mag;
+	const ticks: number[] = [];
+	for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) {
+		ticks.push(Math.round(v / step) * step);
+	}
+	return ticks;
+}
+
+/** UTC date label with dots, e.g. 2022.01.01 (never a trailing -01). */
+export function dateLabel(ts: number): string {
+	const d = new Date(ts);
+	const pad = (n: number) => String(n).padStart(2, "0");
+	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
+}
+
+const pctSeries = (s: (number | null)[] | undefined): number[] => {
+	let prev = 0;
+	return (s ?? []).map((v) => {
+		if (v == null || !Number.isFinite(v)) return prev;
+		prev = v * 100;
+		return prev;
+	});
+};
+
+/** Cumulative-return curve in percent for a trial, or null without a usable curve. */
+export function curveView(trial: ScreenTrial | undefined | null) {
+	const curve = trial?.curve;
+	if (!curve || !curve.t || curve.t.length < 2) return null;
+	const rule = pctSeries(curve.rule);
+	const hold = pctSeries(curve.hold);
+	const all = [...rule, ...hold];
+	return {
+		t: curve.t,
+		rule,
+		hold,
+		labels: curve.t.map(dateLabel),
+		ticks: niceTicks(Math.min(...all), Math.max(...all)),
+	};
+}
+
+export interface ScreenTile {
+	id: string;
+	group: string;
+	name: string;
+	label: string;
+	tip: string;
+}
+
+/** The rule tiles for a (doc, feature, trial): entry direction/indicator, fill cost, exit holding. */
+export function screenRule(doc: ScreenDoc, f: ScreenFeature, trial: ScreenTrial): ScreenTile[] {
+	const fixed = doc.fixed_sign;
+	const sign = fixed ?? trial.train_sign;
+	const signs = new Set((trial.folds ?? []).map((fold) => fold.train_sign));
+	const changed = fixed == null && signs.size > 1;
+	const directionLabel = changed ? "부호 바뀜" : sign >= 0 ? "순방향" : "역추세";
+	const directionName = sign >= 0 ? "기준 위면 롱" : "기준 위면 숏";
+	const directionTip = fixed != null
+		? `방향 부호 ${fixed > 0 ? "+1" : "-1"}로 고정되어 있어, 기준(${fixed > 0 ? "+1" : "-1"}) 위면 ${fixed > 0 ? "롱" : "숏"}으로 들어간다.`
+		: changed
+			? "학습 연도마다 방향 부호가 달라, 해마다 부호가 바뀐다."
+			: sign >= 0
+				? "학습 구간에서 방향 부호가 +1이라 순방향으로 들어간다."
+				: "학습 구간에서 방향 부호가 -1이라 역추세로 들어간다.";
+	const tiles: ScreenTile[] = [
+		{
+			id: "indicator",
+			group: "entry",
+			name: featureName(f),
+			label: f.tradeable === false ? "참고 지표" : "지표",
+			tip: featureDef(f) || f.feature,
+		},
+		{ id: "direction", group: "entry", name: directionName, label: directionLabel, tip: directionTip },
+		{
+			id: "fill",
+			group: "fill",
+			name: `편도 ${Math.round(doc.cost_per_side * 10000)}bp`,
+			label: "비용",
+			tip: `편도 비용 ${Math.round(doc.cost_per_side * 10000)}bp를 적용한다.`,
+		},
+		{
+			id: "hold",
+			group: "exit",
+			name: `${trial.h}${doc.unit} 보유`,
+			label: "보유",
+			tip: `${trial.h}${doc.unit} 동안 보유한다.`,
+		},
+	];
+	if (doc.regime === "down") {
+		tiles.push({
